import{_ as e,c as l,o as a,b0 as d}from"./chunks/framework.BpbtKNwe.js";const r="/aillm-docs/assets/v2-e8710f3414adbb1284a64548b6e399ee_1440w.BFkMTjY2.jpg",n="/aillm-docs/assets/2025-11-17-2138.Bw7TupOo.svg",o="/aillm-docs/assets/2025-11-17-2138-002.D98DDNXK.svg",s="/aillm-docs/assets/image-20251119075723036.BLtvjxcZ.png",i="/aillm-docs/assets/2025-11-17-2138-003.DMBjlUvB.svg",P=JSON.parse('{"title":"LV005-MCP简介","description":null,"frontmatter":{"title":"LV005-MCP简介","date":"2025-11-28T19:54:44.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/llm/mcp/126b154d69743be2a79715fa","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-28T19:54:44.958Z","fulluuid":"2a79715fa54341d6b917bfda298edd57","useduuid":"2a79715fa"}},"headers":[],"relativePath":"sdoc/llm/mcp/126b154d69743be2a79715fa.md","filePath":"sdoc/05-LLM/07-MCP/LV005-MCP简介.md","lastUpdated":1767430713000}'),g={name:"sdoc/llm/mcp/126b154d69743be2a79715fa.md"};function c(h,t,f,p,x,y){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="lv005-mcp简介" tabindex="-1">LV005-MCP简介 <a class="header-anchor" href="#lv005-mcp简介" aria-label="Permalink to &quot;LV005-MCP简介&quot;">​</a></h1><h2 id="一、mcp-概述" tabindex="-1">一、MCP 概述 <a class="header-anchor" href="#一、mcp-概述" aria-label="Permalink to &quot;一、MCP 概述&quot;">​</a></h2><h3 id="_1-mcp-是什么" tabindex="-1">1. MCP 是什么？ <a class="header-anchor" href="#_1-mcp-是什么" aria-label="Permalink to &quot;1. MCP 是什么？&quot;">​</a></h3><p><strong>模型上下文协议（MCP, Model Context Protocol）</strong> 是一种为 AI 模型设计的通用上下文通信协议。它让模型与外部工具、数据资源和运行环境之间建立一个统一、安全、可扩展的接口。</p><p>可以把 MCP 理解为“AI 世界的 USB-C” —— 用一条标准化通道，让模型与一切外部系统互联。</p><img src="'+r+'" alt="img" style="zoom:50%;"><blockquote><p><a href="https://mcp-docs.cn/introduction" target="_blank" rel="noreferrer">MCP 简介 - MCP 中文文档</a></p><p><a href="https://mcp.programnotes.cn/zh" target="_blank" rel="noreferrer">Claude MCP - 模型上下文协议</a></p></blockquote><h3 id="_2-为什么要有mcp" tabindex="-1">2. 为什么要有MCP？ <a class="header-anchor" href="#_2-为什么要有mcp" aria-label="Permalink to &quot;2. 为什么要有MCP？&quot;">​</a></h3><h4 id="_2-1-n×m-问题-模型与工具的碎片化集成" tabindex="-1">2.1 N×M 问题：模型与工具的碎片化集成 <a class="header-anchor" href="#_2-1-n×m-问题-模型与工具的碎片化集成" aria-label="Permalink to &quot;2.1 N×M 问题：模型与工具的碎片化集成&quot;">​</a></h4><p>在早期的 AI 系统中，每个模型与外部系统都需要编写独立的适配层，形成所谓的 <strong>N×M 问题</strong>。当模型数量（N）和工具数量（M）增加时，开发复杂度呈指数级上升。下表总结了碎片化集成带来的典型症状：</p><table tabindex="0"><thead><tr><th style="text-align:left;">症状</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;">重复开发</td><td style="text-align:left;">每新增一个工具或模型都需重新集成</td></tr><tr><td style="text-align:left;">难以复用</td><td style="text-align:left;">不同厂商的接口规范互不兼容</td></tr><tr><td style="text-align:left;">上下文割裂</td><td style="text-align:left;">模型无法直接访问实时数据或系统状态</td></tr></tbody></table><p>结果：AI 助手被困于“信息孤岛”，用户需频繁手动粘贴数据以弥补接口缺口。</p><p>下方流程图展示了传统集成模型的结构：</p><p><img src="'+n+'" alt="2025-11-17-2138.svg"></p><h4 id="_2-2-从-n×m-到-m-n" tabindex="-1">2.2 从 N×M 到 M+N <a class="header-anchor" href="#_2-2-从-n×m-到-m-n" aria-label="Permalink to &quot;2.2 从 N×M 到 M+N&quot;">​</a></h4><p>为解决上述复杂性，Model Context Protocol（MCP, Model Context Protocol）引入统一的“翻译层”，作为模型与工具之间的协议桥梁。每个模型和工具只需实现一次 MCP 接口，即可互操作。</p><p>下方流程图展示了统一接口模型的结构：</p><p><img src="'+o+'" alt="2025-11-17-2138-002"></p><p>这种结构使系统复杂度从 <code>N×M</code> 降至 <code>N+M</code>，大幅降低开发与维护成本。协议借鉴了 <strong>语言服务器协议（LSP, Language Server Protocol）</strong> 的成功经验，强调以下特性：</p><ul><li><strong>可发现性</strong>：客户端可动态查询可用工具；</li><li><strong>能力声明</strong>：每端声明自身支持的功能；</li><li><strong>生命周期管理</strong>：连接与资源动态加载与释放；</li><li><strong>通知机制</strong>：服务端主动推送变化事件。</li></ul><h4 id="_2-3-function-calling-的局限" tabindex="-1">2.3 Function Calling 的局限 <a class="header-anchor" href="#_2-3-function-calling-的局限" aria-label="Permalink to &quot;2.3 Function Calling 的局限&quot;">​</a></h4><p>OpenAI、Anthropic 等厂商早期的 <strong>函数调用（Function Calling）</strong> 能力，使模型可调用 API，但各厂商实现不一致，开发者需维护多套 JSON Schema 与调用逻辑。</p><p>下表总结了 Function Calling 模式的主要局限：</p><table tabindex="0"><thead><tr><th style="text-align:left;">局限</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">无标准化</td><td style="text-align:left;">不同模型的函数定义与参数格式不兼容</td></tr><tr><td style="text-align:left;">扩展性差</td><td style="text-align:left;">每新增函数需重新注册与解析</td></tr><tr><td style="text-align:left;">维护成本高</td><td style="text-align:left;">工具与模型紧耦合，难以复用</td></tr></tbody></table><p>随着模型和工具数量的增加，传统 Function Calling 模式在生态扩展性上逐渐失效。</p><h4 id="_2-4-mcp-的提出-通用上下文协议" tabindex="-1">2.4 MCP 的提出：通用上下文协议 <a class="header-anchor" href="#_2-4-mcp-的提出-通用上下文协议" aria-label="Permalink to &quot;2.4 MCP 的提出：通用上下文协议&quot;">​</a></h4><p>为根治上述问题，<strong>Anthropic 于 2024 年 11 月发布 Model Context Protocol（MCP, Model Context Protocol）</strong>，并在 2025 年 6 月推出更新规范。MCP 建立了统一的三层结构：</p><img src="'+s+'" alt="image-20251119075723036" style="zoom:50%;"><table tabindex="0"><thead><tr><th style="text-align:left;">层级</th><th style="text-align:left;">角色</th><th style="text-align:left;">主要职责</th></tr></thead><tbody><tr><td style="text-align:left;">Host</td><td style="text-align:left;">模型运行宿主，如 IDE、桌面客户端</td><td style="text-align:left;">主机进程是 MCP 协议的核心协调者。它负责管理客户端实例的生命周期，控制连接权限，并执行安全策略。主机还负责协调 AI/LLM 集成，确保整个系统的平稳运行。</td></tr><tr><td style="text-align:left;">Client</td><td style="text-align:left;">协议适配层</td><td style="text-align:left;">客户端由主机创建，用于维护与服务器的独立连接。每个客户端都与一个服务器保持 1:1 的关系，确保连接的隔离性和安全性。</td></tr><tr><td style="text-align:left;">Server</td><td style="text-align:left;">外部工具或数据源</td><td style="text-align:left;">服务器负责公开资源和工具，可以独立运行并通过客户端请求采样。服务器可以是本地的也可以是远程的，为系统提供各种功能。</td></tr></tbody></table><ul><li><p><strong>MCP Hosts</strong>: 如 Claude Desktop、IDE 或 AI 工具，希望通过 MCP 访问数据的程序</p></li><li><p><strong>MCP Clients</strong>: 维护与服务器一对一连接的协议客户端</p></li><li><p><strong>MCP Servers</strong>: 轻量级程序，通过标准的 Model Context Protocol 提供特定能力</p></li><li><p><strong>本地数据源</strong>: MCP 服务器可安全访问的计算机文件、数据库和服务</p></li><li><p><strong>远程服务</strong>: MCP 服务器可连接的互联网上的外部系统（如通过 APIs）</p></li></ul><p>MCP 使用 <strong>JSON-RPC 2.0</strong> 作为消息格式，核心字段如下：</p><table tabindex="0"><thead><tr><th style="text-align:left;">字段</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>method</code></td><td style="text-align:left;">方法名称（如 tools/list、resources/get）</td></tr><tr><td style="text-align:left;"><code>params</code></td><td style="text-align:left;">参数对象</td></tr><tr><td style="text-align:left;"><code>id</code></td><td style="text-align:left;">请求标识符</td></tr><tr><td style="text-align:left;"><code>result</code> / <code>error</code></td><td style="text-align:left;">响应结果或错误描述</td></tr></tbody></table><h3 id="_3-mcp-的发展历程" tabindex="-1">3. MCP 的发展历程 <a class="header-anchor" href="#_3-mcp-的发展历程" aria-label="Permalink to &quot;3. MCP 的发展历程&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">时间</th><th style="text-align:left;">事件</th><th style="text-align:left;">影响</th></tr></thead><tbody><tr><td style="text-align:left;">2024-11</td><td style="text-align:left;">Anthropic 发布 MCP 规范与参考实现</td><td style="text-align:left;">统一模型与外部系统集成标准</td></tr><tr><td style="text-align:left;">2024-12</td><td style="text-align:left;">Block、Apollo、Zed、Replit 等早期接入</td><td style="text-align:left;">开发者生态启动</td></tr><tr><td style="text-align:left;">2025-02</td><td style="text-align:left;">开源社区贡献超 1000 个服务器与连接器</td><td style="text-align:left;">生态快速增长</td></tr><tr><td style="text-align:left;">2025-03</td><td style="text-align:left;">GPT-5 / ChatGPT 全面兼容 MCP</td><td style="text-align:left;">成为主流标准</td></tr><tr><td style="text-align:left;">2025-05</td><td style="text-align:left;">Google A2A 协议兼容 MCP</td><td style="text-align:left;">实现跨厂商互操作</td></tr><tr><td style="text-align:left;">2025-07</td><td style="text-align:left;">IDE 工具普及 MCP 客户端</td><td style="text-align:left;">用户可配置多源工具调用</td></tr></tbody></table><h3 id="_4-小结" tabindex="-1">4. 小结 <a class="header-anchor" href="#_4-小结" aria-label="Permalink to &quot;4. 小结&quot;">​</a></h3><p>MCP 的出现，使模型具备了“即插即用”的外部访问能力。它统一了工具调用、资源访问与上下文交互的协议层，为 AI 系统提供了类似 <strong>USB-C</strong> 的标准接口。</p><h2 id="二、架构与角色" tabindex="-1">二、架构与角色 <a class="header-anchor" href="#二、架构与角色" aria-label="Permalink to &quot;二、架构与角色&quot;">​</a></h2><p>前面其实已经提到过了，主要实现下面三个角色，这里再简单总结一下：</p><table tabindex="0"><thead><tr><th style="text-align:left;">角色</th><th style="text-align:left;">描述</th><th style="text-align:left;">主要职责</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Host（主机）</strong></td><td style="text-align:left;">模型运行的宿主环境，如 IDE、桌面应用或 CLI</td><td style="text-align:left;">启动模型进程并建立客户端连接</td></tr><tr><td style="text-align:left;"><strong>Client（客户端）</strong></td><td style="text-align:left;">代理层，位于模型与外部系统之间</td><td style="text-align:left;">转发消息、维护上下文、缓存资源元数据</td></tr><tr><td style="text-align:left;"><strong>Server（服务器）</strong></td><td style="text-align:left;">提供具体功能或数据接口</td><td style="text-align:left;">实现 MCP 规范，暴露工具、资源与提示模板</td></tr></tbody></table><p>下方流程图展示了 MCP 的典型交互结构：</p><p><img src="'+i+'" alt="2025-11-17-2138-003"></p><p><strong>运行机制说明</strong></p><p>模型通过 Client 向 Server 发现可用能力，Server 响应可调用的工具（Tools）、资源（Resources）和提示模板（Prompts）。Client 负责中继、缓存与权限控制，所有通信通过 JSON-RPC 请求/响应完成，确保安全与一致性。</p><h2 id="三、协议原语-primitives" tabindex="-1">三、协议原语（Primitives） <a class="header-anchor" href="#三、协议原语-primitives" aria-label="Permalink to &quot;三、协议原语（Primitives）&quot;">​</a></h2><p>MCP 的核心由三类原语（Primitive）构成，分别定义了模型可访问的能力类型。下表总结了三类原语及其典型用途：</p><table tabindex="0"><thead><tr><th style="text-align:left;">原语</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Tools（工具）</strong></td><td style="text-align:left;">模型可调用的具体函数或操作</td><td style="text-align:left;">创建事件、查询数据库、发送邮件</td></tr><tr><td style="text-align:left;"><strong>Resources（资源）</strong></td><td style="text-align:left;">模型可访问的数据对象</td><td style="text-align:left;">文件、文档、数据库表、API 响应</td></tr><tr><td style="text-align:left;"><strong>Prompts（提示模板）</strong></td><td style="text-align:left;">定义任务上下文的文本模板</td><td style="text-align:left;">不同任务场景下的系统提示</td></tr></tbody></table><p>这些原语共同描述了 MCP Server 能向模型提供的能力清单。模型可通过 <code>tools/list</code>、<code>resources/list</code> 等方法动态发现，再按需调用，实现灵活扩展。</p>',47)])])}const b=e(g,[["render",c]]);export{P as __pageData,b as default};
